// src/provider/minimax-cn.ts
var MiniMaxCnProvider = class {
  baseUrl = "https://api.minimax.cn/anthropic";
  sdkType = "Anthropic";
  name = "minimax-cn";
  getBaseUrl() {
    return this.baseUrl;
  }
  getSdkType() {
    return this.sdkType;
  }
  getProviderName() {
    return this.name;
  }
  /**
   * 根据 curl --request GET \
   * --url https://api.minimax.cn/v1/models \
   * --header 'Authorization: Bearer <token>' 动态获取modellist
   */
  async getModelList(apiKey) {
    if (!apiKey) {
      throw new Error("API key is required");
    }
    try {
      const response = await fetch("https://api.minimax.cn/v1/models", {
        method: "GET",
        headers: {
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json"
        }
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      if (data && data.data && Array.isArray(data.data)) {
        return data.data.map((model) => model.id);
      }
      return [];
    } catch (error) {
      console.error("Failed to get model list:", error);
      throw error;
    }
  }
};

