var ModelProviderService = class {
  providers = /* @__PURE__ */ new Map();
  store;
  constructor(store) {
    this.store = store || new ProviderStore();
    this.registerDefaultProviders();
  }
  /** 注册默认的Provider */
  registerDefaultProviders() {
    this.registerProvider(new MiniMaxCnProvider());
  }
  /**
   * 注册模型服务商
   * @param provider Provider实例
   */
  registerProvider(provider) {
    const name = provider.getProviderName();
    this.providers.set(name, provider);
  }
  /**
   * 获取已注册的模型服务商列表
   * @returns Provider名称列表
   */
  getRegisteredProviders() {
    return Array.from(this.providers.keys());
  }
  /**
   * 获取指定模型服务商实例
   * @param providerName Provider名称
   * @returns Provider实例
   */
  getProvider(providerName) {
    return this.providers.get(providerName);
  }
  /**
   * 获取指定模型服务商的模型列表
   * @param providerName Provider名称
   * @param apiKey API密钥
   * @returns 模型列表
   */
  async getModelList(providerName, apiKey) {
    const provider = this.providers.get(providerName);
    if (!provider) {
      throw new Error(`Provider '${providerName}' not found`);
    }
    if (!apiKey) {
      throw new Error("API key is required");
    }
    return provider.getModelList(apiKey);
  }
  /**
   * 保存Provider配置
   * @param providerName Provider名称
   * @param config 配置信息
   */
  async saveProviderConfig(providerName, config2) {
    const provider = this.providers.get(providerName);
    if (!provider) {
      throw new Error(`Provider '${providerName}' not found`);
    }
    await this.store.saveConfig(providerName, config2);
  }
  /**
   * 获取Provider配置
   * @param providerName Provider名称
   * @returns 配置信息
   */
  async getProviderConfig(providerName) {
    const provider = this.providers.get(providerName);
    if (!provider) {
      throw new Error(`Provider '${providerName}' not found`);
    }
    return this.store.getConfig(providerName);
  }
  /**
   * 获取Provider的基础URL
   * @param providerName Provider名称
   * @returns 基础URL
   */
  getProviderBaseUrl(providerName) {
    const provider = this.providers.get(providerName);
    if (!provider) {
      throw new Error(`Provider '${providerName}' not found`);
    }
    return provider.getBaseUrl();
  }
  /**
   * 获取Provider的SDK类型
   * @param providerName Provider名称
   * @returns SDK类型
   */
  getProviderSdkType(providerName) {
    const provider = this.providers.get(providerName);
    if (!provider) {
      throw new Error(`Provider '${providerName}' not found`);
    }
    return provider.getSdkType();
  }
  /**
   * 检查Provider是否已注册
   * @param providerName Provider名称
   * @returns 是否已注册
   */
  hasProvider(providerName) {
    return this.providers.has(providerName);
  }
};

